document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("deck-form"),t=document.getElementById("deck-result");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("deck-length").value),s=parseFloat(document.getElementById("deck-width").value),o=parseFloat(document.getElementById("deck-board-size").value),i=parseFloat(document.getElementById("deck-board-length").value),r=parseFloat(document.getElementById("deck-joist-spacing").value),a=parseFloat(document.getElementById("deck-joist-size").value),d=parseFloat(document.getElementById("deck-material-type").value),l=document.getElementById("include-railings").checked;if(n<=0||s<=0)return t.textContent="Please enter valid deck dimensions.",void 0;const p=n*s;let c=Math.ceil(12*s/o)*Math.ceil(n/i);const g=Math.ceil(.1*c),m=c+g,u=Math.floor(12*n/r)+1,$=u+2,h=s+2,v=n,f=Math.ceil(v/12),b=Math.ceil(n/8)+1,y=2*u,x=Math.ceil(32*m),k=2*b,F=p*d,C=$*(2.5*h),M=45*f,w=35*b,B=2.5*y+.12*x+6*k,D=25*b,E=2*(n+s)-8,I=l?20*E:0,j=F+C+M+w+B+D+I,P=m*i*o*1.25/12,q=$*h*a*2/12,T={3:"Pressure-Treated Lumber",6:"Cedar Lumber",10:"Composite Decking",12:"Premium Composite",15:"Capped Composite",18:"PVC Decking"}[d],L=j/p,z=8*p,H=j+z;var R;t.innerHTML=`\n        <div class="cost-summary">\n          <h3>💰 Deck Cost Calculator Results</h3>\n          <div class="cost-highlight">\n            <h4>${n}' × ${s}' Deck (${p} sq ft)</h4>\n            <p><strong>Material Cost: $${j.toFixed(0)}</strong> (${T})</p>\n            <p><strong>Cost per sq ft: $${L.toFixed(2)}</strong></p>\n            <p>Estimated labor: $${z.toFixed(0)} | <strong>Total project: $${H.toFixed(0)}</strong></p>\n          </div>\n        </div>\n        \n        <div class="result-section">\n          <h4>📏 How Many Decking Boards You Need:</h4>\n          <div class="board-calculation">\n            <p><strong>${m} deck boards</strong> (${i}' long × ${o}" wide)</p>\n            <p>Base requirement: ${c} boards</p>\n            <p>Waste allowance: ${g} extra boards (10%)</p>\n            <p>Total board feet: ${P.toFixed(0)} bd ft</p>\n          </div>\n        </div>\n        \n        <div class="result-framing">\n          <h4>🔨 Deck Framing Materials:</h4>\n          <p><strong>${$} joists</strong> (2×${a} × ${h.toFixed(1)}')</p>\n          <p>- ${u} field joists at ${r}" spacing</p>\n          <p>- 2 rim joists (perimeter)</p>\n          <p><strong>${f} beam sections</strong> (double 2×${a})</p>\n          <p><strong>${b} posts</strong> (4×4 pressure-treated)</p>\n          <p><strong>${b} concrete footings</strong> (below frost line)</p>\n          <p>Framing lumber: ${q.toFixed(0)} bd ft</p>\n        </div>\n        \n        <div class="result-hardware">\n          <h4>🔩 Hardware & Fasteners Needed:</h4>\n          <p><strong>${x} deck screws</strong> (2.5" stainless steel or coated)</p>\n          <p><strong>${y} joist hangers</strong> (galvanized steel)</p>\n          <p><strong>${k} lag bolts</strong> (1/2" × 6" galvanized)</p>\n          <p>Joist hanger nails: 5 lbs</p>\n          <p>Construction adhesive: 4-6 tubes</p>\n          ${l?`<p><strong>Railing materials:</strong> ${E} linear feet</p>`:""}\n        </div>\n        \n        <div class="result-costs">\n          <h4>💵 Detailed Cost Breakdown:</h4>\n          <table style="width:100%; border-collapse: collapse;">\n            <tr><td>Decking materials (${T})</td><td style="text-align:right"><strong>$${F.toFixed(0)}</strong></td></tr>\n            <tr><td>Framing lumber (joists)</td><td style="text-align:right">$${C.toFixed(0)}</td></tr>\n            <tr><td>Beams and posts</td><td style="text-align:right">$${(M+w).toFixed(0)}</td></tr>\n            <tr><td>Hardware & fasteners</td><td style="text-align:right">$${B.toFixed(0)}</td></tr>\n            <tr><td>Concrete footings</td><td style="text-align:right">$${D.toFixed(0)}</td></tr>\n            ${l?`<tr><td>Railing materials</td><td style="text-align:right">$${I.toFixed(0)}</td></tr>`:""}\n            <tr style="border-top: 2px solid #333; font-weight: bold;"><td>Total Materials</td><td style="text-align:right">$${j.toFixed(0)}</td></tr>\n          </table>\n          <p><em>Prices vary by location and supplier. Add permits ($100-500) and tools if needed.</em></p>\n        </div>\n        \n        <div class="material-comparison">\n          <h4>🔄 Material Cost Comparison (${p} sq ft deck):</h4>\n          <p>Pressure-treated: $${(3*p+C+M+w+B+D).toFixed(0)} (lowest cost)</p>\n          <p>Cedar: $${(6*p+C+M+w+B+D).toFixed(0)} (natural beauty)</p>\n          <p>Composite: $${(12*p+C+M+w+B+D).toFixed(0)} (low maintenance)</p>\n          <p>Premium composite: $${(15*p+C+M+w+B+D).toFixed(0)} (best quality)</p>\n        </div>\n        \n        <div class="result-tips">\n          <h4>💡 Professional Tips:</h4>\n          <p>📐 <strong>Composite decking:</strong> Requires 16" max joist spacing (12" preferred)</p>\n          <p>🏠 <strong>Permit required:</strong> Most areas require permits for decks over 30" high</p>\n          <p>📦 <strong>Delivery:</strong> Order all decking from same production lot for color consistency</p>\n          <p>⏰ <strong>Installation time:</strong> ${Math.ceil(p/100)} week(s) for DIY, 2-3 days for professionals</p>\n          <p>🔧 <strong>Tools needed:</strong> Circular saw, drill, level, chalk line, measuring tape</p>\n          <p>🛡️ <strong>Maintenance:</strong> ${R=d,R<=6?"Annual staining/sealing required":"Minimal maintenance - just cleaning"}</p>\n        </div>\n        \n        <div class="next-steps">\n          <h4>🎯 Next Steps for Your Deck Project:</h4>\n          <ol>\n            <li>Check local building codes and obtain permits</li>\n            <li>Get quotes from local lumber yards and suppliers</li>\n            <li>Consider hiring professionals for foundation work</li>\n            <li>Plan for utilities (electrical, plumbing) before building</li>\n            <li>Schedule delivery 2-3 days before starting construction</li>\n          </ol>\n        </div>\n      `})});